<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { actOnAdminResource, getAdminResources } from '@/api/admin'
import type { MonthlyApplication, MonthlyPlan } from '@/types/monthly'
import type { ParkingLot } from '@/types/parking'
import { MONTHLY_STATUS, VEHICLE_TYPE } from '@/constants/enums'
import { formatMoney } from '@/utils/format'
import StatusTag from '@/components/common/StatusTag.vue'

const tab=ref<'PLAN'|'APPLICATION'>('PLAN');const plans=ref<MonthlyPlan[]>([]);const applications=ref<MonthlyApplication[]>([]);const lots=ref<ParkingLot[]>([]);const loading=ref(false);const planDialog=ref(false);const auditDialog=ref(false);const editingId=ref<number>();const currentApp=ref<MonthlyApplication>();const planForm=reactive({parkingLotId:undefined as number|undefined,planName:'',vehicleType:'SMALL' as 'SMALL'|'NEW_ENERGY',monthCount:1,price:399,description:'',status:1 as 0|1});const auditForm=reactive({status:1 as 1|2,auditRemark:''})
async function load(){loading.value=true;try{if(tab.value==='PLAN')plans.value=(await getAdminResources<MonthlyPlan>({resourceType:'MONTHLY_PLAN',pageSize:100})).list;else applications.value=(await getAdminResources<MonthlyApplication>({resourceType:'MONTHLY_APPLICATION',pageSize:100})).list}finally{loading.value=false}}
function openPlan(plan?:MonthlyPlan){editingId.value=plan?.id;Object.assign(planForm,plan??{parkingLotId:lots.value[0]?.id,planName:'',vehicleType:'SMALL',monthCount:1,price:399,description:'',status:1});planDialog.value=true}
async function savePlan(){if(!planForm.parkingLotId||!planForm.planName.trim()){ElMessage.warning('请填写停车场和套餐名称');return}await ElMessageBox.confirm('确认保存月租套餐？','保存确认');const lot=lots.value.find(l=>l.id===planForm.parkingLotId);await actOnAdminResource({resourceType:'MONTHLY_PLAN',action:editingId.value?'UPDATE':'CREATE',id:editingId.value,payload:{...planForm,parkingLotName:lot?.lotName??''}});ElMessage.success('月租套餐已保存');planDialog.value=false;await load()}
async function removePlan(plan:MonthlyPlan){await ElMessageBox.confirm(`确定删除套餐 ${plan.planName}？`,'删除确认',{type:'warning'});await actOnAdminResource({resourceType:'MONTHLY_PLAN',action:'DELETE',id:plan.id});ElMessage.success('套餐已删除');await load()}
function openAudit(app:MonthlyApplication){currentApp.value=app;Object.assign(auditForm,{status:1,auditRemark:''});auditDialog.value=true}
async function audit(){if(!currentApp.value)return;if(auditForm.status===2&&!auditForm.auditRemark.trim()){ElMessage.warning('审核拒绝必须填写原因');return}await ElMessageBox.confirm(`确认${auditForm.status===1?'通过':'拒绝'}该月租申请？`,'审核确认',{type:'warning'});await actOnAdminResource({resourceType:'MONTHLY_APPLICATION',action:'AUDIT',id:currentApp.value.id,payload:{...auditForm}});ElMessage.success('审核结果已保存');auditDialog.value=false;await load()}
onMounted(async()=>{lots.value=(await getAdminResources<ParkingLot>({resourceType:'PARKING_LOT',pageSize:100})).list;await load()})
</script>
<template><div><h1 class="page-title">月租综合管理</h1><p class="page-subtitle">管理月租套餐并审核申请；通过记录直接作为有效月租。</p><div class="panel"><el-tabs v-model="tab" @tab-change="load"><el-tab-pane label="月租套餐" name="PLAN"/><el-tab-pane label="月租申请" name="APPLICATION"/></el-tabs><div v-if="tab==='PLAN'" class="toolbar"><el-button type="primary" @click="openPlan()">新增套餐</el-button></div><el-table v-loading="loading" :data="tab==='PLAN'?plans:applications"><template v-if="tab==='PLAN'"><el-table-column prop="planName" label="套餐名称" min-width="150"/><el-table-column prop="parkingLotName" label="停车场" min-width="170"/><el-table-column label="车辆类型" width="110"><template #default="{row}">{{ VEHICLE_TYPE[row.vehicleType as keyof typeof VEHICLE_TYPE] }}</template></el-table-column><el-table-column prop="monthCount" label="月数" width="70"/><el-table-column label="价格" width="100"><template #default="{row}">{{ formatMoney(row.price) }}</template></el-table-column><el-table-column prop="description" label="说明" min-width="180"/><el-table-column label="状态" width="90"><template #default="{row}"><StatusTag :label="row.status===1?'启用':'停用'" :status="row.status===1?1:3"/></template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button text type="primary" @click="openPlan(row)">编辑</el-button><el-button text type="danger" @click="removePlan(row)">删除</el-button></template></el-table-column></template><template v-else><el-table-column prop="applicationNo" label="申请编号" min-width="165"/><el-table-column prop="userName" label="用户" width="100"/><el-table-column prop="plateNumber" label="车辆" width="110"/><el-table-column prop="parkingLotName" label="停车场" min-width="160"/><el-table-column prop="planName" label="套餐" min-width="140"/><el-table-column label="有效期" min-width="190"><template #default="{row}">{{ row.startDate }} 至 {{ row.endDate }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><StatusTag :label="MONTHLY_STATUS[row.status as keyof typeof MONTHLY_STATUS]" :status="row.status"/></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="row.status===0" text type="primary" @click="openAudit(row)">审核</el-button><span v-else class="text-muted">--</span></template></el-table-column></template></el-table></div><el-dialog v-model="planDialog" :title="editingId?'编辑套餐':'新增套餐'" width="min(560px,94vw)"><el-form :model="planForm" label-position="top"><el-form-item label="停车场" required><el-select v-model="planForm.parkingLotId" class="full-width"><el-option v-for="lot in lots" :key="lot.id" :label="lot.lotName" :value="lot.id"/></el-select></el-form-item><el-form-item label="套餐名称" required><el-input v-model="planForm.planName"/></el-form-item><div class="two"><el-form-item label="车辆类型"><el-select v-model="planForm.vehicleType"><el-option label="小型车" value="SMALL"/><el-option label="新能源车" value="NEW_ENERGY"/></el-select></el-form-item><el-form-item label="月数"><el-input-number v-model="planForm.monthCount" :min="1" :max="12"/></el-form-item><el-form-item label="价格"><el-input-number v-model="planForm.price" :min="0" :precision="2"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="planForm.status"><el-radio :value="1">启用</el-radio><el-radio :value="0">停用</el-radio></el-radio-group></el-form-item></div><el-form-item label="说明"><el-input v-model="planForm.description" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="planDialog=false">取消</el-button><el-button type="primary" @click="savePlan">保存</el-button></template></el-dialog><el-dialog v-model="auditDialog" title="审核月租申请" width="min(520px,94vw)"><el-descriptions v-if="currentApp" :column="1" border><el-descriptions-item label="车辆">{{ currentApp.plateNumber }}</el-descriptions-item><el-descriptions-item label="套餐">{{ currentApp.planName }}</el-descriptions-item><el-descriptions-item label="有效期">{{ currentApp.startDate }} 至 {{ currentApp.endDate }}</el-descriptions-item></el-descriptions><el-form :model="auditForm" label-position="top" class="audit-form"><el-form-item label="审核结果"><el-radio-group v-model="auditForm.status"><el-radio :value="1">通过</el-radio><el-radio :value="2">拒绝</el-radio></el-radio-group></el-form-item><el-form-item label="审核意见" :required="auditForm.status===2"><el-input v-model="auditForm.auditRemark" type="textarea" :rows="3" placeholder="拒绝时必须填写原因"/></el-form-item></el-form><template #footer><el-button @click="auditDialog=false">取消</el-button><el-button type="primary" @click="audit">确认审核</el-button></template></el-dialog></div></template>
<style scoped>.two{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.audit-form{margin-top:18px}@media(max-width:600px){.two{grid-template-columns:1fr}}</style>
